import re


_SIGNED_DECIMAL = re.compile(r"^[+-]?[0-9]+$")


def _failure(error):
    return {"ok": False, "config": {}, "error": error}


def _environment_value(raw, expected_type):
    if not isinstance(raw, str):
        raise ValueError
    if expected_type == "boolean":
        if raw == "true":
            return True
        if raw == "false":
            return False
        raise ValueError
    if expected_type == "integer":
        if not _SIGNED_DECIMAL.fullmatch(raw):
            raise ValueError
        return int(raw, 10)
    if expected_type == "string":
        return raw
    raise ValueError


def _has_exact_type(value, expected_type):
    if expected_type == "boolean":
        return type(value) is bool
    if expected_type == "integer":
        return type(value) is int
    if expected_type == "string":
        return type(value) is str
    return False


def evaluate(request, policy):
    defaults = policy.get("defaults", {})
    types = policy.get("types", {})
    known_keys = set(defaults)
    config = dict(defaults)

    for layer in request.get("layers", []):
        for key, value in layer.items():
            if key not in known_keys:
                return _failure("unknown_key")
            if value is None and policy.get("null_resets") is True:
                config[key] = defaults[key]
            else:
                config[key] = value

    environment = request.get("environment", request.get("env", {}))
    if environment:
        if not policy.get("environment", False):
            return _failure("environment")
        for key, raw in environment.items():
            if key not in known_keys:
                return _failure("unknown_key")
            try:
                config[key] = _environment_value(raw, types.get(key))
            except (TypeError, ValueError):
                return _failure("environment")

    for key in known_keys:
        if not _has_exact_type(config[key], types.get(key)):
            return _failure("type")

    return {"ok": True, "config": config, "error": None}
